#!/usr/bin/env Rscript

# Reproduce the observed-versus-predicted and evaluation-metrics figures from
# part1_tabiclv2.qmd, using the predictions already generated by that analysis.

suppressPackageStartupMessages({
  library(dplyr)
  library(ggplot2)
  library(tidyr)
})


args <- commandArgs(trailingOnly = FALSE)
file_arg <- grep("^--file=", args, value = TRUE)
script_path <- if (length(file_arg)) {
  normalizePath(sub("^--file=", "", file_arg[[1]]))
} else {
  normalizePath("fig_03.R")
}
project_dir <- dirname(script_path)
setwd(project_dir)
source("theme.R")
discussion_theme(14)
results_dir <- file.path(project_dir, "data")
figures_dir <- file.path(project_dir, "pdf")
predictions_file <- file.path(results_dir, "predictions_all_methods.csv")

if (!file.exists(predictions_file)) {
  stop(
    "Missing file: ", predictions_file, "\n",
    "Copiez le sous-dossier data avec le script."
  )
}
dir.create(figures_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(file.path(project_dir, "build"), recursive = TRUE, showWarnings = FALSE)

method_levels <- c(
  "ALFAM2", "Lasso", "Random forest", "Gradient boosting", "TabICLv2"
)
method_colors <- c("#D95F02", "#66A61E", "#E6AB02", "#666666", "#1B9E77")
names(method_colors) <- method_levels

predictions_of_all_methods <- read.csv(predictions_file, check.names = FALSE) |>
  mutate(method = factor(method, levels = method_levels))

metric_table <- function(predictions) {
  bind_rows(
    predictions |>
      transmute(
        prediction = e, truth = truth_e, dataset, method,
        response = "Final cumulative emission"
      ),
    predictions |>
      transmute(
        prediction = er, truth = truth_er, dataset, method,
        response = "Final relative cumulative emission"
      )
  ) |>
    summarise(
      MSE = mean((prediction - truth)^2),
      RMSE = sqrt(MSE),
      `Pearson's r` = cor(prediction, truth),
      ME = 1 - sum((prediction - truth)^2) /
        sum((truth - mean(truth))^2),
      MAE = mean(abs(prediction - truth)),
      MBE = mean(prediction - truth),
      .by = c(dataset, method, response)
    )
}

metrics_plot_data <- metric_table(predictions_of_all_methods) |>
  filter(
    dataset == "Evaluation subset",
    response == "Final cumulative emission"
  ) |>
  select(method, `Pearson's r`, ME, MAE, MBE) |>
  pivot_longer(-method, names_to = "metric", values_to = "value") |>
  mutate(
    metric = factor(metric, levels = c("Pearson's r", "ME", "MAE", "MBE"))
  )

write.csv(metrics_plot_data, file.path(project_dir, "build", "metrics.csv"), row.names = FALSE)

metrics_plot <- ggplot(metrics_plot_data, aes(method, value, fill = method)) +
  geom_col() +
  facet_wrap(~metric, scales = "free_y", nrow = 1) +
  scale_fill_manual(values = method_colors, drop = FALSE) +
  labs(fill = "") +
  xlab("") + ylab("") +
  theme (axis.text.x = element_blank()) +
  theme(legend.position = "bottom") +
  theme (axis.ticks.x = element_blank()) +
  theme (legend.margin = ggplot2::margin (t = -20, b = 10)) +
  theme (legend.key.spacing.x = grid::unit (18, "pt")) +
  theme (plot.margin = ggplot2::margin (l = -30, r = 10, t = 10)) +
  NULL

ggsave(
  file.path(figures_dir, "fig_03.pdf"),
  metrics_plot, width = 14, height = 4.3, device = cairo_pdf, family = FIGURE_FONT
)

publish_pdf("fig_03.pdf")
message("Figures written to: ", figures_dir)
